--- view schema/helpers ---
type UnknownRecord = Record<string, unknown>;

function isRecord(value: unknown): value is UnknownRecord {
	return Boolean(value) && typeof value === "object" && !Array.isArray(value);
}

function hasOptionalType(
	value: UnknownRecord,
	key: string,
	type: "string" | "boolean",
): boolean {
	return value[key] === undefined || typeof value[key] === type;
}

export function isExternalHttpUrl(value: unknown): value is string {
	if (typeof value !== "string") return false;
	try {
		const url = new URL(value);
		return url.protocol === "https:" || url.protocol === "http:";
	} catch {
		return false;
	}
}

function isBlock(value: unknown): boolean {
	if (!isRecord(value) || typeof value.type !== "string") return false;
	if (value.type === "text") {
		return (
			typeof value.value === "string" &&
			hasOptionalType(value, "label", "string") &&
			hasOptionalType(value, "muted", "boolean")
		);
	}
	if (value.type === "code") return typeof value.value === "string";
	if (value.type === "form") {
		return (
			isRecord(value.schema) &&
			(value.initialValues === undefined || isRecord(value.initialValues)) &&
			(value.values === undefined || isRecord(value.values))
		);
	}
	if (value.type !== "diff" || !Array.isArray(value.fields)) return false;
	return value.fields.every(
		(field) =>
			isRecord(field) &&
			typeof field.label === "string" &&
			typeof field.after === "string" &&
			hasOptionalType(field, "before", "string"),
	);
}

function hasOptionalStringArray(value: UnknownRecord, key: string): boolean {
	return (
		value[key] === undefined ||
		(Array.isArray(value[key]) &&
			value[key].every((item) => typeof item === "string"))
	);
}

function hasValidActionBase(value: UnknownRecord): boolean {
	if (typeof value.id !== "string" || typeof value.label !== "string")
		return false;
	if (
		value.variant !== undefined &&
		!["primary", "outline", "ghost", "destructive"].includes(
			String(value.variant),
		)
	)
		return false;
	if (
		value.icon !== undefined &&
		!["check", "external", "x"].includes(String(value.icon))
	)
		return false;
	return (
		hasOptionalType(value, "confirm", "boolean") &&
		hasOptionalType(value, "confirmPrompt", "string") &&
		hasOptionalType(value, "terminal", "boolean") &&
		hasOptionalType(value, "resolvedLabel", "string") &&
		hasOptionalType(value, "submitFormAs", "string")
	);
}

function isLinkAction(value: unknown): boolean {
	if (!isRecord(value)) return false;
	if (
		!hasValidActionBase(value) ||
		!isExternalHttpUrl(value.href) ||
		value.tool !== undefined ||
		value.args !== undefined
	) {
		return false;
	}
	if (
		value.variant !== undefined &&
		!["primary", "outline", "ghost", "destructive"].includes(
			String(value.variant),
		)
	) {
		return false;
	}
	return (
		(value.icon === undefined || value.icon === "external") &&
		hasOptionalType(value, "terminal", "boolean")
	);
}

function isToolAction(value: unknown): boolean {
	if (!isRecord(value) || !hasValidActionBase(value)) return false;
	return (
		typeof value.tool === "string" &&
		value.tool.length > 0 &&
		(value.args === undefined || isRecord(value.args)) &&
		value.href === undefined
	);
}

function isApprovalToolAction(value: unknown): boolean {
	if (!isRecord(value) || !hasValidActionBase(value)) return false;
	if (
		value.tool !== "resolve_lobu_approval" ||
		!isRecord(value.args) ||
		!Number.isInteger(value.args.run_id) ||
		Number(value.args.run_id) < 1 ||
		!["approve", "reject"].includes(String(value.args.decision)) ||
		value.id !== value.args.decision ||
		value.href !== undefined
	) {
		return false;
	}
	return value.submitFormAs === undefined || value.submitFormAs === "input";
}

function isInteractionAction(value: unknown): boolean {
	return isLinkAction(value) || isToolAction(value);
}

function isInteractionBlock(value: unknown): boolean {
	if (isBlock(value)) return true;
	if (!isRecord(value) || value.type !== "entity") return false;
	if (
		typeof value.id !== "string" ||
		typeof value.label !== "string" ||
		typeof value.name !== "string" ||
		!hasOptionalStringArray(value, "details")
	)
		return false;
	if (value.recordLink !== undefined && !isInteractionAction(value.recordLink))
		return false;
	return (
		value.sourceLinks === undefined ||
		(Array.isArray(value.sourceLinks) &&
			value.sourceLinks.every(isInteractionAction))
	);
}

export const SPA_HOSTED_VIEW_SOURCE = "lobu-spa";

/**
 * Runtime boundary for a view authored by Lobu's own SPA host. These views can
 * contain brokered tool actions because the parent frame pins every handler and
 * sensitive argument. The source marker is added by McpAppFrame after the view
 * is built; server-authored external views never receive it.
 */
function isSpaHostedInteractionView(value: unknown): value is UnknownRecord {
	if (
		!isRecord(value) ||
		value.version !== 1 ||
		value.source !== SPA_HOSTED_VIEW_SOURCE
	)
		return false;
	if (value.blocks === undefined && value.actions === undefined) return false;
	if (
		value.blocks !== undefined &&
		(!Array.isArray(value.blocks) ||
			value.blocks.length > 100 ||
			!value.blocks.every(isInteractionBlock))
	)
		return false;
	if (
		value.actions !== undefined &&
		(!Array.isArray(value.actions) ||
			value.actions.length > 10 ||
			!value.actions.every(isInteractionAction))
	)
		return false;
	if (!hasOptionalType(value, "title", "string")) return false;
	return (
		value.tone === undefined ||
		value.tone === "warning" ||
		value.tone === "default" ||
		value.tone === "bare"
	);
}

/**
 * Runtime boundary for both supported trust domains: link-only server-authored
 * LobuViewV1 and executable views authored by Lobu's own SPA frame host.
 */
export function isLobuView(value: unknown): value is UnknownRecord {
	if (isSpaHostedInteractionView(value)) return true;
	return isServerAuthoredLobuView(value);
}

/** External MCP hosts may execute only this server-authored, tightly-scoped view. */
export function isServerAuthoredLobuView(
	value: unknown,
): value is UnknownRecord {
	if (!isRecord(value) || value.version !== 1) return false;
	if (value.source !== undefined) return false;
	if (!Array.isArray(value.blocks) || value.blocks.length > 100) return false;
	if (!Array.isArray(value.actions) || value.actions.length > 10) return false;
	if (
		!value.blocks.every(isBlock) ||
		!value.actions.every(
			(action) => isLinkAction(action) || isApprovalToolAction(action),
		)
	)
		return false;
	if (!hasOptionalType(value, "title", "string")) return false;
	return (
		value.tone === undefined ||
		value.tone === "warning" ||
		value.tone === "default" ||
		value.tone === "bare"
	);
}

