function DataTable({
	rows,
	columns,
	openLink,
}: {
	rows: UnknownRecord[];
	columns?: Array<{ name: string; type?: string }>;
	openLink: (href: string) => void;
}) {
	const [page, setPage] = useState(0);
	const pageSize = 10;
	const names =
		columns?.map((column) => column.name) ??
		[...new Set(rows.flatMap((row) => Object.keys(row)))].slice(0, 12);
	const pageCount = Math.max(1, Math.ceil(rows.length / pageSize));
	const visibleRows = rows.slice(page * pageSize, (page + 1) * pageSize);
	return (
		<div>
			<div className="overflow-x-auto">
				<table className="w-full border-collapse text-xs">
					<thead>
						<tr>
							{names.map((name) => (
								<th
									key={name}
									className="border border-border px-2 py-1.5 text-left font-medium"
								>
									{humanize(name)}
								</th>
							))}
						</tr>
					</thead>
					<tbody>
						{visibleRows.map((row, rowIndex) => (
							// biome-ignore lint/suspicious/noArrayIndexKey: SQL rows can be duplicate and have no guaranteed primary key; page order is immutable.
							<tr key={`${page}:${rowIndex}`}>
								{names.map((name) => {
									const cell = row[name];
									return (
										<td
											key={name}
											className="max-w-80 border border-border px-2 py-1.5 align-top"
										>
											{isRecord(cell) || Array.isArray(cell) ? (
												<details>
													<summary className="cursor-pointer">
														Structured value
													</summary>
													<pre className="mt-1 max-h-56 overflow-auto whitespace-pre-wrap">
														{stringify(cell)}
													</pre>
												</details>
											) : (
												<ValueView value={cell} openLink={openLink} depth={1} />
											)}
										</td>
									);
								})}
							</tr>
						))}
					</tbody>
				</table>
			</div>
			{pageCount > 1 ? (
				<div className="mt-2 flex items-center justify-end gap-1.5">
					<Button
						type="button"
						size="sm"
						variant="outline"
						disabled={page === 0}
						onClick={() => setPage((p) => p - 1)}
					>
						<ChevronLeft className="h-3.5 w-3.5" />
						<span className="sr-only">Previous page</span>
					</Button>
					<span className="text-muted-foreground text-xs">
						{page + 1} / {pageCount}
					</span>
					<Button
						type="button"
						size="sm"
						variant="outline"
						disabled={page + 1 >= pageCount}
						onClick={() => setPage((p) => p + 1)}
					>
						<ChevronRight className="h-3.5 w-3.5" />
						<span className="sr-only">Next page</span>
					</Button>
				</div>
			) : null}
		</div>
	);
}

function isSqlResult(value: UnknownRecord): boolean {
	return (
		Array.isArray(value.rows) &&
		Array.isArray(value.columns) &&
		typeof value.total_count === "number"
	);
}

const SqlResult: FC<{
	value: UnknownRecord;
	openLink: (href: string) => void;
}> = ({ value, openLink }) => {
	const rows = (value.rows as unknown[]).filter(isRecord);
	const columns = (value.columns as unknown[])
		.filter(isRecord)
		.filter((column) => typeof column.name === "string")
		.map((column) => ({
			name: String(column.name),
			type: String(column.type ?? ""),
		}));
	const meta = `${String(value.total_count)} rows · ${String(value.execution_time_ms ?? 0)} ms`;
	return (
		<Section title="SQL results" meta={meta}>
			{typeof value.error === "string" ? (
				<div className="mb-2 rounded-md border border-destructive/40 bg-destructive/10 p-2 text-sm text-destructive">
					{value.error}
				</div>
			) : null}
			<DataTable rows={rows} columns={columns} openLink={openLink} />
			{value.has_more === true ? (
				<p className="mt-2 text-muted-foreground text-xs">
					More rows are available from the server.
				</p>
			) : null}
		</Section>
	);
};

function isSdkResult(value: UnknownRecord): boolean {
	return typeof value.success === "boolean" && Array.isArray(value.logs);
}

const SdkResult: FC<{
	value: UnknownRecord;
	openLink: (href: string) => void;
}> = ({ value, openLink }) => {
	const error = isRecord(value.error) ? value.error : null;
	const sideEffects = Array.isArray(value.side_effect_preview)
		? value.side_effect_preview
		: [];
	const logs = Array.isArray(value.logs) ? value.logs : [];
	const trace = Array.isArray(value.sdk_call_trace) ? value.sdk_call_trace : [];
	return (
		<div className="space-y-2">
			<Section
				title="SDK result"
				meta={`${String(value.duration_ms ?? 0)} ms${value.dry_run === true ? " · dry run" : ""}`}
			>
				<div className="mb-2 flex items-center gap-1.5 text-xs">
					{value.success === true ? (
						<CheckCircle2 className="h-4 w-4 text-green-600" />
					) : (
						<AlertCircle className="h-4 w-4 text-destructive" />
					)}
					<span>{value.success === true ? "Completed" : "Failed"}</span>
				</div>
				{error ? (
					<div className="mb-3 rounded-md border border-destructive/40 bg-destructive/10 p-2">
						<div className="font-medium text-sm text-destructive">
							{String(error.message ?? error.name ?? "SDK error")}
						</div>
						{error.code ? (
							<div className="mt-1 text-muted-foreground text-xs">
								{String(error.code)} ·{" "}
								{error.retryable === true ? "retryable" : "not retryable"}
							</div>
						) : null}
					</div>
				) : null}
				{value.return_value !== undefined ? (
					<ValueView value={value.return_value} openLink={openLink} />
				) : value.success === true ? (
					<p className="text-muted-foreground text-xs">No return value.</p>
				) : null}
			</Section>
			{sideEffects.length > 0 ? (
				<Section
					title="Dry-run side effects"
					meta={`${sideEffects.length} skipped`}
				>
					<ValueView value={sideEffects} openLink={openLink} />
				</Section>
			) : null}
			{logs.length > 0 || trace.length > 0 ? (
				<details className={cn(FILLED_BOX, "px-3 py-2 text-xs")}>
					<summary className="cursor-pointer font-medium">
						Logs and SDK trace
					</summary>
					<div className="mt-2 space-y-2">
						{logs.length > 0 ? (
							<ValueView value={logs} openLink={openLink} />
						) : null}
						{trace.length > 0 ? (
							<ValueView value={trace} openLink={openLink} />
						) : null}
					</div>
				</details>
			) : null}
		</div>
	);
};

function isSdkSearchResult(value: UnknownRecord): boolean {
	return (
		typeof value.query === "string" &&
		typeof value.match_count === "number" &&
		Array.isArray(value.results)
	);
}

const GenericResult: FC<{
	value: UnknownRecord;
	openLink: (href: string) => void;
}> = ({ value, openLink }) => {
	if (isSdkSearchResult(value)) {
		return (
			<Section title="SDK documentation" meta={`${value.match_count} matches`}>
				<div className="space-y-2">
					{(value.results as unknown[]).map((result) => (
						<pre
							key={String(result)}
							className="overflow-x-auto whitespace-pre-wrap rounded-md border border-border/70 bg-background/40 p-2 text-xs"
						>
							{String(result)}
						</pre>
					))}
				</div>
			</Section>
		);
	}
	const title =
		Array.isArray(value.content) || Array.isArray(value.matches)
			? "Memory results"
			: typeof value.semantic_type === "string" && typeof value.id === "number"
				? "Memory saved"
				: "Lobu result";
	return (
		<Section title={title}>
			<ValueView value={value} openLink={openLink} />
		</Section>
	);
};

export const McpResultView: FC<{
	value: unknown;
	onAction: (action: InteractionAction) => void;
	openLink: (href: string) => void;
	pendingId?: string | null;
	resolvedId?: string | null;
	allowSpaHostedViews?: boolean;
}> = ({
	value,
	onAction,
	openLink,
	pendingId,
	resolvedId,
	allowSpaHostedViews = false,
}) => {
	const validView = allowSpaHostedViews
		? isLobuView(value)
		: isServerAuthoredLobuView(value);
	if (validView) {
		return (
			<InteractionCard
				view={value as InteractionView}
				onAction={onAction}
				pendingId={pendingId}
				resolvedId={resolvedId}
			/>
		);
	}
	if (!isRecord(value)) {
		return (
			<Section title="Lobu result">
				<ValueView value={value} openLink={openLink} />
			</Section>
		);
	}
	if (isSqlResult(value))
		return <SqlResult value={value} openLink={openLink} />;
	if (isSdkResult(value))
		return <SdkResult value={value} openLink={openLink} />;
	return <GenericResult value={value} openLink={openLink} />;
};

